{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title",
        "summary_text",
        "top_performer_text",
        "regional_sales_heading",
        "sales_table",
        "quick_actions_heading",
        "view_dashboard_button"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Quarterly Sales Performance Overview",
        "variant": "h2"
      },
      "children": []
    },
    "summary_text": {
      "type": "Text",
      "props": {
        "text": "The sales data across the North, South, and East regions has been analyzed to compare quarterly performance and identify the top-performing region annually."
      },
      "children": []
    },
    "top_performer_text": {
      "type": "Text",
      "props": {
        "text": "The East region achieved the highest total annual sales with 470 units."
      },
      "children": []
    },
    "regional_sales_heading": {
      "type": "Text",
      "props": {
        "text": "Regional Sales Analysis Data",
        "variant": "h3"
      },
      "children": []
    },
    "sales_table": {
      "type": "Table",
      "props": {
        "title": "Quarterly Sales by Region",
        "columns": [
          {
            "key": "Region",
            "label": "Region"
          },
          {
            "key": "Q1 Sales",
            "label": "Q1 Sales"
          },
          {
            "key": "Q2 Sales",
            "label": "Q2 Sales"
          },
          {
            "key": "Q3 Sales",
            "label": "Q3 Sales"
          },
          {
            "key": "Q4 Sales",
            "label": "Q4 Sales"
          }
        ],
        "rows": [
          {
            "Region": "North",
            "Q1 Sales": 100,
            "Q2 Sales": 110,
            "Q3 Sales": 90,
            "Q4 Sales": 120
          },
          {
            "Region": "South",
            "Q1 Sales": 80,
            "Q2 Sales": 95,
            "Q3 Sales": 100,
            "Q4 Sales": 115
          },
          {
            "Region": "East",
            "Q1 Sales": 120,
            "Q2 Sales": 105,
            "Q3 Sales": 115,
            "Q4 Sales": 130
          }
        ],
        "domain": "generic",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "quick_actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "view_dashboard_button": {
      "type": "Button",
      "props": {
        "label": "View Dashboard"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/sales-dashboard"
          }
        }
      },
      "children": []
    }
  }
}
